=== 1923-1994 (vd4dot gemm) ===
1923	static void q1_gemm_64_vd4dot_vl1024(int n, float * s, size_t bs, const void * vx,
1924	const block_q8_0x4 * vy, int nr, int nc) {
1925	const int    nb   = n / QK1_0;
1926	const int    ng   = n / QK8_0;   // q8 groups per row
1927	const size_t vl32 = 64;          // i32 lanes  = rows
1928	const size_t vl8  = 64 * 4;      // i8  lanes  = rows x 4 columns
1929	   7 
1930	// the row tile's activation quants, de-interleaved: aq[m * n + column]
1931	int8_t * aq = (int8_t *) __builtin_alloca(4 * (size_t) n);
1932	  10 
1933	const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);
1934	  12 
1935	for (int y = 0; y < nr / 4; ++y) {
1936	const block_q8_0x4 * a_ptr = vy + (size_t) y * ng;
1937	  15 
1938	for (int g = 0; g < ng; ++g) {
1939	const vuint32m1_t  q  = __riscv_vle32_v_u32m1((const uint32_t *) a_ptr[g].qs, QK8_0);
1940	const vuint16mf2_t lo = __riscv_vnsrl_wx_u16mf2(q,  0, QK8_0);  // rows 0,1
1941	const vuint16mf2_t hi = __riscv_vnsrl_wx_u16mf2(q, 16, QK8_0);  // rows 2,3
1942	uint8_t * dst = (uint8_t *) aq + (size_t) g * QK8_0;
1943	__riscv_vse8_v_u8mf4(dst + 0 * (size_t) n, __riscv_vnsrl_wx_u8mf4(lo, 0, QK8_0), QK8_0);
1944	__riscv_vse8_v_u8mf4(dst + 1 * (size_t) n, __riscv_vnsrl_wx_u8mf4(lo, 8, QK8_0), QK8_0);
1945	__riscv_vse8_v_u8mf4(dst + 2 * (size_t) n, __riscv_vnsrl_wx_u8mf4(hi, 0, QK8_0), QK8_0);
1946	__riscv_vse8_v_u8mf4(dst + 3 * (size_t) n, __riscv_vnsrl_wx_u8mf4(hi, 8, QK8_0), QK8_0);
1947	}
1948	  26 
1949	for (int x = 0; x < nc / 64; ++x) {
1950	const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1951	vfloat32m2_t sumf0 = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
1952	vfloat32m2_t sumf1 = sumf0, sumf2 = sumf0, sumf3 = sumf0;
1953	for (int l = 0; l < nb; ++l) {
1954	q1_prefetch_block(bx, l, nb);
1955	const vfloat32m2_t dx     = q1_expand_fp16_64_m2(bx[l].d);
1956	const uint8_t *    planes = (const uint8_t *) bx[l].qs;
1957	for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1958	const int        g  = l * (QK1_0 / QK8_0) + k;
1959	const uint32_t * a0 = (const uint32_t *) (aq + 0 * (size_t) n + (size_t) g * QK8_0);
1960	const uint32_t * a1 = (const uint32_t *) (aq + 1 * (size_t) n + (size_t) g * QK8_0);
1961	const uint32_t * a2 = (const uint32_t *) (aq + 2 * (size_t) n + (size_t) g * QK8_0);
1962	const uint32_t * a3 = (const uint32_t *) (aq + 3 * (size_t) n + (size_t) g * QK8_0);
1963	vint32m2_t acc0 = __riscv_vmv_v_x_i32m2(0, vl32);
1964	vint32m2_t acc1 = acc0, acc2 = acc0, acc3 = acc0;
1965	// the 4 output rows already share one weight vector, so
1966	// one asm block covers all 4 dots and their vsetvli
1967	for (int c = 0; c < QK8_0; c += 4) {
1968	const vbool4_t  m = __riscv_vlm_v_b4(planes + (size_t) (k * (QK8_0 / 4) + c / 4) * 32, vl8);
1969	const vint8m2_t w = __riscv_vmerge_vxm_i8m2(vneg1, 1, m, vl8);
1970	q1_vd4dots_4acc_m2(&acc0, &acc1, &acc2, &acc3, w,
1971	a0[c / 4], a1[c / 4], a2[c / 4], a3[c / 4]);
1972	}
1973	const ggml_half * ad = a_ptr[g].d;
1974	sumf0 = __riscv_vfmacc_vv_f32m2(sumf0,
1975	__riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[0]), vl32),
1976	__riscv_vfcvt_f_x_v_f32m2(acc0, vl32), vl32);
1977	sumf1 = __riscv_vfmacc_vv_f32m2(sumf1,
1978	__riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[1]), vl32),
1979	__riscv_vfcvt_f_x_v_f32m2(acc1, vl32), vl32);
1980	sumf2 = __riscv_vfmacc_vv_f32m2(sumf2,
1981	__riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[2]), vl32),
1982	__riscv_vfcvt_f_x_v_f32m2(acc2, vl32), vl32);
1983	sumf3 = __riscv_vfmacc_vv_f32m2(sumf3,
1984	__riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[3]), vl32),
1985	__riscv_vfcvt_f_x_v_f32m2(acc3, vl32), vl32);
1986	}
1987	}
1988	__riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 0) * bs + (size_t) x * 64, sumf0, vl32);
1989	__riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 1) * bs + (size_t) x * 64, sumf1, vl32);
1990	__riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 2) * bs + (size_t) x * 64, sumf2, vl32);
1991	__riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 3) * bs + (size_t) x * 64, sumf3, vl32);
1992	}
1993	}
1994	}

2101	static void q1_gemm_64x1_vl1024(int n, float * s, size_t bs, const void * vx, const block_q8_0x4 * vy, int nr, int nc) {
2102	    const int    nb   = n / QK1_0;
2103	    const int    nbq8 = n / QK8_0;
2104	    const size_t vl   = 64;
2105	    for (int y = 0; y < nr / 4; ++y) {
2106	        const block_q8_0x4 * a_ptr = vy + (size_t) y * nbq8;
2107	        for (int x = 0; x < nc / 64; ++x) {
2108	            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
2109	            vfloat32m2_t sumf0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
2110	            vfloat32m2_t sumf1 = sumf0, sumf2 = sumf0, sumf3 = sumf0;
2111	            for (int l = 0; l < nb; ++l) {
2112	                q1_prefetch_block(bx, l, nb);
2113	                const vfloat32m2_t dx    = q1_expand_fp16_64_m2(bx[l].d);
2114	                vfloat32m2_t       facc0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
2115	                vfloat32m2_t       facc1 = facc0, facc2 = facc0, facc3 = facc0;
2116	                for (int k = 0; k < QK1_0 / QK8_0; ++k) {
2117	                    const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
2118	                    vint16m1_t sumi0 = __riscv_vmv_v_x_i16m1(0, vl);
2119	                    vint16m1_t sumi1 = sumi0, sumi2 = sumi0, sumi3 = sumi0;
2120	                    for (int c = 0; c < QK8_0; ++c) {
2121	                        const vbool16_t sign = __riscv_vlm_v_b16(bx[l].qs[k * QK8_0 + c], vl);
2122	                        const int16_t   a0 = ab->qs[c * 4 + 0], a1 = ab->qs[c * 4 + 1];
2123	                        const int16_t   a2 = ab->qs[c * 4 + 2], a3 = ab->qs[c * 4 + 3];
2124	                        sumi0 = __riscv_vsub_vx_i16m1(sumi0, a0, vl);
2125	                        sumi0 = __riscv_vadd_vx_i16m1_mu(sign, sumi0, sumi0, (int16_t) (2 * a0), vl);
2126	                        sumi1 = __riscv_vsub_vx_i16m1(sumi1, a1, vl);
2127	                        sumi1 = __riscv_vadd_vx_i16m1_mu(sign, sumi1, sumi1, (int16_t) (2 * a1), vl);
2128	                        sumi2 = __riscv_vsub_vx_i16m1(sumi2, a2, vl);
2129	                        sumi2 = __riscv_vadd_vx_i16m1_mu(sign, sumi2, sumi2, (int16_t) (2 * a2), vl);
2130	                        sumi3 = __riscv_vsub_vx_i16m1(sumi3, a3, vl);
2131	                        sumi3 = __riscv_vadd_vx_i16m1_mu(sign, sumi3, sumi3, (int16_t) (2 * a3), vl);
2132	                    }
2133	                    facc0 = __riscv_vfmacc_vf_f32m2(facc0, GGML_CPU_FP16_TO_FP32(ab->d[0]),
2134	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi0, vl), vl), vl);
2135	                    facc1 = __riscv_vfmacc_vf_f32m2(facc1, GGML_CPU_FP16_TO_FP32(ab->d[1]),
2136	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi1, vl), vl), vl);
2137	                    facc2 = __riscv_vfmacc_vf_f32m2(facc2, GGML_CPU_FP16_TO_FP32(ab->d[2]),
2138	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi2, vl), vl), vl);
2139	                    facc3 = __riscv_vfmacc_vf_f32m2(facc3, GGML_CPU_FP16_TO_FP32(ab->d[3]),
2140	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi3, vl), vl), vl);
2141	                }
2142	                sumf0 = __riscv_vfmacc_vv_f32m2(sumf0, dx, facc0, vl);
2143	                sumf1 = __riscv_vfmacc_vv_f32m2(sumf1, dx, facc1, vl);
2144	                sumf2 = __riscv_vfmacc_vv_f32m2(sumf2, dx, facc2, vl);
2145	                sumf3 = __riscv_vfmacc_vv_f32m2(sumf3, dx, facc3, vl);
2146	            }
2147	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 0) * bs + (size_t) x * 64, sumf0, vl);
2148	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 1) * bs + (size_t) x * 64, sumf1, vl);
2149	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 2) * bs + (size_t) x * 64, sumf2, vl);
2150	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 3) * bs + (size_t) x * 64, sumf3, vl);
2151	        }
2152	    }
2153	}
